78	/**
79	 * Consume SSE data payloads (ending with `[DONE]`) and yield StreamChunks.
80	 * Malformed JSON payloads abort the stream with `MALFORMED_RESPONSE`.
81	 * @param payloads - SSE data payloads from {@link parseSse}, `[DONE]`-terminated.
82	 * @returns deltas as they arrive; `block-end`s, `usage`, and `finish` are all deferred to the `[DONE]` sentinel.
83	 *   A `stop` (or absent) finish with no opened blocks is a degenerate provider completion and maps to an
84	 *   `EMPTY_RESPONSE` error finish instead of a successful empty message.
85	 */
86	export async function* translate(payloads: AsyncIterable<string>): AsyncGenerator<StreamChunk> {
87	  let nextIndex = 0
88	  let textBlock: OpenBlock | undefined
89	  let reasoningBlock: OpenBlock | undefined
90	  const toolBlocks = new Map<number, OpenBlock>()
91	  const order: OpenBlock[] = []
92	  let pendingFinish: FinishReason | undefined
93	  let pendingUsage: TokenUsage | undefined
94	
95	  function open(kind: OpenBlock['kind']): OpenBlock {
96	    const block: OpenBlock = { index: nextIndex++, kind, text: '' }
97	    order.push(block)
98	    return block
99	  }
100	
101	  for await (const payload of payloads) {
102	    if (payload === DONE) {
103	      for (const block of order) {
104	        yield { type: 'block-end', index: block.index, block: closeBlock(block) }
105	      }
106	      if (pendingUsage) yield { type: 'usage', usage: pendingUsage }
107	      const reason = pendingFinish ?? { kind: 'stop' as const }
108	      yield {
109	        type: 'finish',
110	        reason: reason.kind === 'stop' && order.length === 0
111	          ? {
112	            kind: 'error',
113	            failure: { message: 'model returned a completed response with no content', code: EMPTY_RESPONSE_CODE },
114	          }
115	          : reason,
116	      }
117	      return
118	    }
119	
120	    let chunk: WireChunk
121	    try {
122	      chunk = JSON.parse(payload) as WireChunk
123	    } catch {
124	      throw new LlmError(`malformed SSE payload: ${payload.slice(0, 120)}`, 'MALFORMED_RESPONSE')
125	    }
126	
127	    for (const choice of chunk.choices ?? []) {
128	      const delta = choice.delta
129	
130	      // Reasoning first: thinking mode interleaves it before text. The
131	      // empty-string first chunk must not open a block.
132	      const reasoning = delta?.reasoning_content
133	      if (typeof reasoning === 'string' && reasoning.length > 0) {
134	        if (!reasoningBlock) {
135	          reasoningBlock = open('reasoning')
136	          yield { type: 'block-start', index: reasoningBlock.index, blockType: 'reasoning' }
137	        }
138	        reasoningBlock.text += reasoning
139	        yield { type: 'reasoning-delta', index: reasoningBlock.index, text: reasoning }
140	      }
141	
142	      const content = delta?.content
143	      if (typeof content === 'string' && content.length > 0) {
144	        if (!textBlock) {
145	          textBlock = open('text')
146	          yield { type: 'block-start', index: textBlock.index, blockType: 'text' }
147	        }
148	        textBlock.text += content
149	        yield { type: 'text-delta', index: textBlock.index, text: content }
150	      }
151	
152	      for (const call of delta?.tool_calls ?? []) {
153	        let block = toolBlocks.get(call.index)
154	        if (!block) {
155	          block = open('tool-call')
156	          toolBlocks.set(call.index, block)
157	          yield { type: 'block-start', index: block.index, blockType: 'tool-call' }
158	        }
159	        if (call.id !== undefined) block.callId = call.id
160	        if (call.function?.name !== undefined) block.name = call.function.name
161	        const fragment = call.function?.arguments ?? ''
162	        block.text += fragment
163	        yield {
164	          type: 'tool-call-delta',
165	          index: block.index,
166	          id: CallId(block.callId ?? ''),
167	          ...block.name !== undefined ? { name: block.name } : {},
168	          argumentsDelta: fragment,
169	        }
170	      }
171	
172	      if (typeof choice.finish_reason === 'string') {
173	        pendingFinish = mapFinishReason(choice.finish_reason)
174	      }
175	    }
176	
177	    // Usage may arrive attached to the finish chunk or as a trailing
178	    // usage-only chunk — keep the latest.
179	    if (chunk.usage) pendingUsage = mapUsage(chunk.usage)
180	  }
181	
182	  // parseSse guarantees the [DONE] sentinel (or throws); reaching here means
183	  // the payload source violated that contract.
184	  throw new LlmError('SSE payload stream ended without [DONE]', 'STREAM_CLOSED')
185	}
