/**
 * Value types shared by this route's configuration, request rendering, and
 * response parsing.
 *
 * @module @deepseek-ai/dsh-llm-claude-code/types
 */

import type { ResolvedRetryPolicy } from '@deepseek-ai/dsh-llm'

/**
 * One model the operator's installation can run, declared by the operator
 * because the harness has no way to interrogate an installation's entitlements.
 */
export interface ClaudeCodeModel {
  /** Model id harness requests select through `GenerateOptions.model`. */
  id: string
  /**
   * Model the installation is asked to run, sent as the product's `model`
   * option. Absent leaves that option off, so the installation runs whatever
   * it is configured to run.
   */
  productModel?: string
  /** Human-readable name for selectors; the id when absent. */
  name?: string
  /** User-facing distinction from otherwise similar entries. */
  description?: string
  /** Maximum combined request and response context, when the operator knows it. */
  contextWindow?: number
  /** Per-request output cap materialized when a caller omits one. */
  maxTokens?: number
}

/** Response effort passed through to the product's `effort` option. */
export type ClaudeCodeEffort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'

/** Thinking policy passed through to the product's `thinking` option. */
export type ClaudeCodeThinking =
  | { type: 'adaptive' }
  | { type: 'enabled'; budgetTokens: number }
  | { type: 'disabled' }

/**
 * Validated configuration for the one route this plugin registers, resolved
 * once at load so a misconfigured composition fails before any request.
 */
export interface ResolvedClaudeCodeOptions {
  /** Provider route registered on `ctx.llm`. */
  readonly provider: string
  /** Route name shown by provider selectors and diagnostics. */
  readonly displayName: string
  /** The models this route accepts, in operator-declared order. */
  readonly models: readonly ClaudeCodeModel[]
  /** Explicit entries layered over the subprocess seam's scrubbed parent environment. */
  readonly env: Readonly<Record<string, string>>
  /** Response effort for every query, or the installation's own when absent. */
  readonly effort?: ClaudeCodeEffort
  /** Thinking policy for every query, or the installation's own when absent. */
  readonly thinking?: ClaudeCodeThinking
  /** Maximum idle interval between messages of one query, in milliseconds. */
  readonly queryTimeoutMs: number
  /** Grace between process-tree termination tiers, in milliseconds. */
  readonly disposeGraceMs: number
  /** Retry policy captured with the route registration. */
  readonly retryPolicy: ResolvedRetryPolicy
}

/** One tool invocation the product returned in its structured answer. */
export interface ClaudeCodeToolCall {
  /** Harness tool name, as offered in the rendered tool section. */
  name: string
  /** Arguments object, re-serialized into the seam's raw-JSON argument string. */
  arguments: Record<string, unknown>
}

/** The product's structured answer to one harness request. */
export interface ClaudeCodeAnswer {
  /** Visible assistant text, empty when the turn is tool calls alone. */
  content: string
  /** Tool calls the harness agent loop executes, in returned order. */
  toolCalls: ClaudeCodeToolCall[]
}

/** One harness request rendered into the product's prompt inputs. */
export interface RenderedRequest {
  /**
   * Custom system prompt replacing the product's own preset, so the harness
   * system prompt is the only standing instruction the model reads.
   */
  systemPrompt: string
  /** Tool section and conversation, rendered as one prompt text. */
  prompt: string
}

/**
 * Plugin configuration and the one explicit resolve step from raw config to
 * validated route facts.
 *
 * @module @deepseek-ai/dsh-llm-claude-code/config
 */

import z from '@deepseek-ai/schemastery'
import { resolveRetryPolicy, RetryPolicySchema } from '@deepseek-ai/dsh-llm'
import type { RetryPolicyConfig } from '@deepseek-ai/dsh-llm'
import { MAX_TIMER_DELAY_MS } from '@deepseek-ai/dsh-timeout'
import type {
  ClaudeCodeEffort,
  ClaudeCodeModel,
  ClaudeCodeThinking,
  ResolvedClaudeCodeOptions,
} from './types.ts'

/**
 * Idle interval between messages of one query. The product streams partial
 * assistant events while it works, so this bounds a silent installation rather
 * than the answer's own duration.
 */
export const DEFAULT_QUERY_TIMEOUT_MS = 300_000

/** Grace between process-tree termination tiers for the installation's CLI. */
export const DEFAULT_DISPOSE_GRACE_MS = 3_000

/** Selectable response efforts, in the product's own order. */
export const CLAUDE_CODE_EFFORTS: readonly ClaudeCodeEffort[] = Object.freeze([
  'low',
  'medium',
  'high',
  'xhigh',
  'max',
])

/**
 * Deployment-owned route facts. The model catalog is configuration with no
 * default: only the operator knows which models their installation may run,
 * and this plugin names none.
 */
export interface Config {
  /** Provider route this plugin registers on `ctx.llm`. */
  provider: string
  /** Route name shown by provider selectors; the route name when absent. */
  displayName?: string
  /** Models this route accepts; a request naming any other fails with `UNKNOWN_MODEL`. */
  models: ClaudeCodeModel[]
  /**
   * Explicit environment entries layered over the subprocess seam's
   * credential-scrubbed parent environment.
   */
  env?: Record<string, string>
  /** Response effort for every query; absent keeps the installation's own. */
  effort?: ClaudeCodeEffort
  /** Thinking policy for every query; absent keeps the installation's own. */
  thinking?: ClaudeCodeThinking
  /** Maximum idle interval between messages of one query (default five minutes). */
  queryTimeoutMs?: number
  /** Grace in milliseconds for CLI process-tree termination (default 3000). */
  disposeGraceMs?: number
  /** Provider-owned model-request retry policy; omission uses normal defaults. */
  retryPolicy?: RetryPolicyConfig
}

const modelSchema: z<ClaudeCodeModel> = z.object({
  id: z.string().required(),
  productModel: z.string(),
  name: z.string(),
  description: z.string(),
  contextWindow: z.number().step(1).min(1),
  maxTokens: z.number().step(1).min(1),
})

const thinkingSchema: z<ClaudeCodeThinking> = z.union([
  z.object({ type: z.const('adaptive').required() }),
  z.object({
    type: z.const('enabled').required(),
    budgetTokens: z.number().step(1).min(1).required(),
  }),
  z.object({ type: z.const('disabled').required() }),
])

export const Config: z<Config> = z.object({
  provider: z.string().required(),
  displayName: z.string(),
  models: z.array(modelSchema).required(),
  env: z.dict(z.string()).default({}),
  effort: z.union([...CLAUDE_CODE_EFFORTS]),
  thinking: thinkingSchema,
  queryTimeoutMs: z.number().min(Number.MIN_VALUE).max(MAX_TIMER_DELAY_MS).default(DEFAULT_QUERY_TIMEOUT_MS),
  disposeGraceMs: z.number().min(Number.MIN_VALUE).max(MAX_TIMER_DELAY_MS).default(DEFAULT_DISPOSE_GRACE_MS),
  retryPolicy: RetryPolicySchema,
})

function assertTimer(value: number, field: string): void {
  if (!Number.isFinite(value) || value <= 0 || value > MAX_TIMER_DELAY_MS) {
    throw new Error(
      `llm-claude-code: ${field} must be a positive finite number no greater than ${MAX_TIMER_DELAY_MS}`,
    )
  }
}

function assertPositiveInteger(value: number | undefined, field: string): void {
  if (value !== undefined && (!Number.isSafeInteger(value) || value <= 0)) {
    throw new Error(`llm-claude-code: ${field} must be a positive safe integer`)
  }
}

/** Validate, deduplicate, and detach the operator-declared model catalog. */
function resolveModels(models: readonly ClaudeCodeModel[]): ClaudeCodeModel[] {
  if (models.length === 0) {
    throw new Error('llm-claude-code: models must declare at least one model this installation may run')
  }
  const seen = new Set<string>()
  return models.map((model) => {
    if (model.id.length === 0) throw new Error('llm-claude-code: model ids must be non-empty')
    if (seen.has(model.id)) throw new Error(`llm-claude-code: duplicate model "${model.id}"`)
    seen.add(model.id)
    if (model.productModel !== undefined && model.productModel.length === 0) {
      throw new Error(`llm-claude-code: model "${model.id}" productModel must be non-empty when present`)
    }
    if (model.name !== undefined && model.name.length === 0) {
      throw new Error(`llm-claude-code: model "${model.id}" has an empty name`)
    }
    assertPositiveInteger(model.contextWindow, `model "${model.id}" contextWindow`)
    assertPositiveInteger(model.maxTokens, `model "${model.id}" maxTokens`)
    return {
      id: model.id,
      ...model.productModel === undefined ? {} : { productModel: model.productModel },
      ...model.name === undefined ? {} : { name: model.name },
      ...model.description === undefined ? {} : { description: model.description },
      ...model.contextWindow === undefined ? {} : { contextWindow: model.contextWindow },
      ...model.maxTokens === undefined ? {} : { maxTokens: model.maxTokens },
    }
  })
}

/** Validate and detach the thinking policy handed to the product unchanged. */
function resolveThinking(thinking: ClaudeCodeThinking | undefined): ClaudeCodeThinking | undefined {
  if (thinking === undefined) return undefined
  switch (thinking.type) {
    case 'adaptive':
    case 'disabled':
      return { type: thinking.type }
    case 'enabled':
      if (!Number.isSafeInteger(thinking.budgetTokens) || thinking.budgetTokens <= 0) {
        throw new Error('llm-claude-code: thinking.budgetTokens must be a positive safe integer')
      }
      return { type: 'enabled', budgetTokens: thinking.budgetTokens }
    default:
      throw new Error('llm-claude-code: thinking.type must be "adaptive", "enabled", or "disabled"')
  }
}

/**
 * Resolve raw plugin config into the immutable facts every request uses.
 * Programmatic construction may bypass Schemastery normalization, so every
 * default and bound is re-judged here and a bad composition fails at load.
 * @param config - raw plugin config from `cordis.yml` or a direct mount.
 * @returns validated, detached route facts.
 */
export function resolveAdapterOptions(config: Config): ResolvedClaudeCodeOptions {
  if (typeof config.provider !== 'string' || config.provider.length === 0) {
    throw new Error('llm-claude-code: provider must name the route this plugin registers')
  }
  if (config.displayName !== undefined && config.displayName.length === 0) {
    throw new Error('llm-claude-code: displayName must be non-empty when present')
  }
  if (config.effort !== undefined && !CLAUDE_CODE_EFFORTS.includes(config.effort)) {
    throw new Error(`llm-claude-code: effort must be one of ${CLAUDE_CODE_EFFORTS.join(', ')}`)
  }
  const queryTimeoutMs = config.queryTimeoutMs ?? DEFAULT_QUERY_TIMEOUT_MS
  const disposeGraceMs = config.disposeGraceMs ?? DEFAULT_DISPOSE_GRACE_MS
  assertTimer(queryTimeoutMs, 'queryTimeoutMs')
  assertTimer(disposeGraceMs, 'disposeGraceMs')
  const thinking = resolveThinking(config.thinking)
  return Object.freeze({
    provider: config.provider,
    displayName: config.displayName ?? config.provider,
    models: Object.freeze(resolveModels(config.models ?? [])),
    env: Object.freeze({ ...config.env }),
    ...config.effort === undefined ? {} : { effort: config.effort },
    ...thinking === undefined ? {} : { thinking },
    queryTimeoutMs,
    disposeGraceMs,
    retryPolicy: resolveRetryPolicy(config.retryPolicy, 'llm-claude-code: retryPolicy'),
  })
}

/**
 * Render one harness request into the product's prompt inputs: the harness
 * system prompt becomes the query's custom system prompt, and the tool
 * definitions plus the whole conversation become one prompt text in log order.
 *
 * Every output here is a pure function of the request the seam hands over, and
 * that request is itself derived from the session log, so a rendered query is
 * reconstructable from the log.
 *
 * @module @deepseek-ai/dsh-llm-claude-code/render
 */

import { contentHasImage, LlmError } from '@deepseek-ai/dsh-llm'
import type { ContentBlock, GenerateOptions, Message, ToolSchema } from '@deepseek-ai/dsh-llm'
import type { RenderedRequest } from './types.ts'

/** Tag prefix framing the rendered conversation when no content already uses it. */
export const TAG_BASE = 'dsh'

/**
 * JSON Schema requested through the product's structured-output option. Tool
 * arguments stay a JSON string because the seam carries raw JSON arguments
 * end-to-end and never re-serializes what the model wrote.
 */
export const RESPONSE_SCHEMA: Record<string, unknown> = Object.freeze({
  type: 'object',
  additionalProperties: false,
  required: ['content', 'toolCalls'],
  properties: {
    content: {
      type: 'string',
      description: 'The reply to show the user. Empty when this turn is tool calls alone.',
    },
    toolCalls: {
      type: 'array',
      description: 'Tool calls to run before the next turn, in the order they should run.',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'arguments'],
        properties: {
          name: { type: 'string', description: 'A tool name offered in the prompt.' },
          arguments: {
            type: 'string',
            description: 'That call\'s arguments as a JSON object, encoded as a JSON string.',
          },
        },
      },
    },
  },
})

/** One rendering pass: the prompt text plus every verbatim string it embedded. */
interface RenderPass {
  readonly text: string
  readonly contents: readonly string[]
}

/** Collects verbatim strings so a later pass can detect tag-prefix collisions. */
class PromptWriter {
  private readonly lines: string[] = []
  readonly contents: string[] = []

  constructor(private readonly ns: string) {}

  /** Append one framing line the harness owns. */
  structure(line: string): void {
    this.lines.push(line)
  }

  /** Append one verbatim string and record it for collision detection. */
  content(text: string): void {
    this.contents.push(text)
    this.lines.push(text)
  }

  /** Append an opening tag with already-escaped attribute values. */
  open(tag: string, attributes: readonly (readonly [string, string])[] = []): void {
    const rendered = attributes.map(([key, value]) => ` ${key}="${value}"`).join('')
    this.lines.push(`<${this.ns}-${tag}${rendered}>`)
  }

  /** Append a closing tag. */
  close(tag: string): void {
    this.lines.push(`</${this.ns}-${tag}>`)
  }

  /** The rendered pass, newline-joined with a trailing newline. */
  finish(): RenderPass {
    return { text: `${this.lines.join('\n')}\n`, contents: this.contents }
  }
}

/** Join every text block of a message or nested tool result. */
function flattenText(blocks: readonly ContentBlock[]): string {
  return blocks.filter(block => block.type === 'text').map(block => block.text).join('')
}

/**
 * Neutralize the two characters that would end an attribute value or its tag.
 * Ids and tool names are harness-minted, so this only guards against a
 * hand-built request carrying an unexpected value.
 */
function attributeValue(raw: string): string {
  return raw.replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;')
}

/** Reject content this text-only prompt cannot carry without silently erasing it. */
function assertTextOnly(message: Message): void {
  if (contentHasImage(message.content)) {
    throw new LlmError(
      'llm-claude-code: the Claude Code prompt route does not support image content',
      'UNSUPPORTED_CONTENT',
    )
  }
}

/** Write one assistant message: its visible text, then each tool call it requested. */
function writeAssistant(writer: PromptWriter, message: Message): void {
  writer.open('assistant')
  const text = flattenText(message.content)
  if (text.length > 0) writer.content(text)
  for (const block of message.content) {
    if (block.type !== 'tool-call') continue
    writer.open('tool-call', [['id', attributeValue(block.id)], ['name', attributeValue(block.name)]])
    writer.content(block.arguments)
    writer.close('tool-call')
  }
  writer.close('assistant')
}

/**
 * Write one user-role message. The harness carries each tool result in its own
 * user message, so a message with text and no results is an ordinary user turn.
 */
function writeUser(writer: PromptWriter, message: Message): void {
  const text = flattenText(message.content)
  const results = message.content.filter(block => block.type === 'tool-result')
  if (text.length > 0 || results.length === 0) {
    writer.open('user')
    writer.content(text)
    writer.close('user')
  }
  for (const result of results) {
    writer.open('tool-result', [
      ['id', attributeValue(result.toolCallId)],
      ['status', result.isError === true ? 'error' : 'ok'],
    ])
    writer.content(flattenText(result.content))
    writer.close('tool-result')
  }
}

/** Write the tool section: what the harness runs, and the schema of each call. */
function writeTools(writer: PromptWriter, tools: readonly ToolSchema[]): void {
  writer.open('tools')
  writer.structure(
    'The harness runs these tools, not you. Ask for a call by putting it in `toolCalls`;'
    + ' its result arrives in the next request.',
  )
  for (const tool of tools) {
    writer.open('tool', [['name', attributeValue(tool.name)]])
    writer.content(tool.description)
    writer.structure('Arguments (JSON Schema):')
    writer.content(JSON.stringify(tool.parameters))
    writer.close('tool')
  }
  writer.close('tools')
}

/** Render the whole prompt text under one tag prefix. */
function renderPass(options: GenerateOptions, ns: string): RenderPass {
  const writer = new PromptWriter(ns)
  writer.structure(
    `Answer the last turn of the conversation below. Elements tagged \`<${ns}-…>\` are the harness's`
    + ' framing; everything between them is the conversation.',
  )
  const tools = options.tools ?? []
  if (tools.length > 0) writeTools(writer, tools)
  writer.open('conversation')
  for (const message of options.messages) {
    assertTextOnly(message)
    switch (message.role) {
      case 'system':
        writer.open('system')
        writer.content(flattenText(message.content))
        writer.close('system')
        break
      case 'assistant':
        writeAssistant(writer, message)
        break
      default:
        writeUser(writer, message)
    }
  }
  writer.close('conversation')
  return writer.finish()
}

/**
 * Choose the smallest tag prefix no rendered content already uses, so a
 * message that itself contains the framing cannot be read as framing.
 * @param contents - every verbatim string the first pass embedded.
 * @returns the base prefix, or the first numbered variant free of collisions.
 */
export function tagNamespace(contents: readonly string[]): string {
  let ns = TAG_BASE
  for (
    let suffix = 2;
    contents.some(text => text.includes(`<${ns}`) || text.includes(`</${ns}`));
    suffix += 1
  ) {
    ns = `${TAG_BASE}${suffix}`
  }
  return ns
}

/**
 * Render one harness request into the product's system prompt and prompt text.
 * @param options - the fully assembled harness request.
 * @returns the custom system prompt and the single prompt text carrying tools and conversation.
 */
export function renderRequest(options: GenerateOptions): RenderedRequest {
  const first = renderPass(options, TAG_BASE)
  const ns = tagNamespace(first.contents)
  return {
    // An absent harness system prompt still replaces the product's preset: the
    // harness owns every standing instruction this route's model reads.
    systemPrompt: options.system ?? '',
    prompt: ns === TAG_BASE ? first.text : renderPass(options, ns).text,
  }
}

/**
 * Map one product result back onto the seam: parse the structured answer into
 * chunks, translate token accounting, and classify a failed query into the
 * seam's provider-neutral error codes.
 *
 * @module @deepseek-ai/dsh-llm-claude-code/response
 */

import type { NonNullableUsage, SDKResultMessage } from '@anthropic-ai/claude-agent-sdk'
import {
  CallId,
  CONTEXT_WINDOW_EXCEEDED_CODE,
  EMPTY_RESPONSE_CODE,
  isContextWindowExceededError,
  isQuotaExceededError,
  LlmError,
  QUOTA_EXCEEDED_CODE,
} from '@deepseek-ai/dsh-llm'
import type { StreamChunk, TokenUsage } from '@deepseek-ai/dsh-llm'
import type { ClaudeCodeAnswer, ClaudeCodeToolCall } from './types.ts'

/** Code for a product result the seam cannot read as one model response. */
export const MALFORMED_RESPONSE_CODE = 'MALFORMED_RESPONSE'

/** Code for a query the product ended without producing its answer. */
export const PRODUCT_ERROR_CODE = 'PRODUCT_ERROR'

/** Code for a query the product stopped at its turn bound. */
export const MAX_TURNS_CODE = 'MAX_TURNS'

function malformed(detail: string): LlmError {
  return new LlmError(`llm-claude-code: ${detail}`, MALFORMED_RESPONSE_CODE)
}

/** Read one required string field of the structured answer. */
function requiredString(source: Record<string, unknown>, field: string, where: string): string {
  const value = source[field]
  if (typeof value !== 'string') throw malformed(`${where} must carry a string "${field}"`)
  return value
}

/**
 * Accept the arguments field in either form the product may emit: the JSON
 * string the schema asks for, or a JSON object when its structured-output
 * enforcement passed one through.
 */
function callArguments(raw: unknown): string {
  if (typeof raw === 'string') return raw
  if (typeof raw === 'object' && raw !== null && !Array.isArray(raw)) return JSON.stringify(raw)
  throw malformed('every tool call must carry "arguments" as a JSON string or object')
}

/**
 * Parse the product's structured output into the answer this route returns.
 * A missing or unreadable structured output is a provider failure, never an
 * empty answer that would silently end the turn.
 * @param structured - the result's `structured_output` value, exactly as delivered.
 * @returns the visible text and the tool calls to hand back to the agent loop.
 */
export function parseAnswer(structured: unknown): ClaudeCodeAnswer {
  if (typeof structured !== 'object' || structured === null || Array.isArray(structured)) {
    throw malformed('the query returned no structured answer')
  }
  const source = structured as Record<string, unknown>
  const content = requiredString(source, 'content', 'the structured answer')
  const rawCalls = source['toolCalls']
  if (!Array.isArray(rawCalls)) {
    throw malformed('the structured answer must carry a "toolCalls" array')
  }
  const toolCalls: ClaudeCodeToolCall[] = rawCalls.map((rawCall) => {
    if (typeof rawCall !== 'object' || rawCall === null || Array.isArray(rawCall)) {
      throw malformed('every tool call must be an object')
    }
    const call = rawCall as Record<string, unknown>
    return {
      name: requiredString(call, 'name', 'every tool call'),
      arguments: callArguments(call['arguments']),
    }
  })
  return { content, toolCalls }
}

/** Read one usage counter across the CLI's JSON boundary, where a field may be absent. */
function tokenCount(value: number | undefined): number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : 0
}

/**
 * Translate the product's token accounting into the seam's disjoint counts.
 * The product already reports uncached input separately from cache reads and
 * writes, so no subtraction is needed.
 * @param usage - the result's usage record.
 * @returns disjoint harness counts; cache fields only when the product reported them.
 */
export function mapUsage(usage: NonNullableUsage): TokenUsage {
  const cacheReadTokens = tokenCount(usage.cache_read_input_tokens)
  const cacheWriteTokens = tokenCount(usage.cache_creation_input_tokens)
  return {
    inputTokens: tokenCount(usage.input_tokens),
    outputTokens: tokenCount(usage.output_tokens),
    ...cacheReadTokens > 0 ? { cacheReadTokens } : {},
    ...cacheWriteTokens > 0 ? { cacheWriteTokens } : {},
  }
}

/**
 * Classify one failed query. Every code, terminal reason, and message the
 * product reported joins one detail string so the seam's shared classifiers
 * see the same evidence they see from an HTTP provider.
 * @param message - the product's result message.
 * @returns the seam-coded failure to throw for this query.
 */
export function resultFailure(message: SDKResultMessage): LlmError {
  const errors = message.subtype === 'success' ? [] : message.errors
  const detail = [message.subtype, message.terminal_reason, message.stop_reason, ...errors]
    .filter(part => typeof part === 'string' && part.length > 0)
    .join(' ')
  const text = `llm-claude-code: the query failed: ${detail}`
  if (isContextWindowExceededError(detail)) return new LlmError(text, CONTEXT_WINDOW_EXCEEDED_CODE)
  if (isQuotaExceededError(detail)) return new LlmError(text, QUOTA_EXCEEDED_CODE)
  switch (message.subtype) {
    case 'success':
      return new LlmError(text, PRODUCT_ERROR_CODE)
    case 'error_max_turns':
      return new LlmError(text, MAX_TURNS_CODE)
    case 'error_max_budget_usd':
      return new LlmError(text, QUOTA_EXCEEDED_CODE)
    case 'error_max_structured_output_retries':
      return new LlmError(text, MALFORMED_RESPONSE_CODE)
    case 'error_during_execution':
      return new LlmError(text, PRODUCT_ERROR_CODE)
  }
}

/**
 * Emit one answer as the seam's chunk protocol: the visible text block first,
 * then one block per tool call, then usage and the terminal finish.
 * @param answer - the parsed structured answer.
 * @param usage - the product's token accounting for this query.
 * @param responseId - the result's own identity, which makes call ids unique per response.
 * @returns the chunks in protocol order.
 */
export function answerChunks(
  answer: ClaudeCodeAnswer,
  usage: NonNullableUsage,
  responseId: string,
): StreamChunk[] {
  if (answer.content.length === 0 && answer.toolCalls.length === 0) {
    throw new LlmError(
      'llm-claude-code: the query completed with no text and no tool calls',
      EMPTY_RESPONSE_CODE,
    )
  }
  const chunks: StreamChunk[] = []
  let index = 0
  if (answer.content.length > 0) {
    chunks.push(
      { type: 'block-start', index, blockType: 'text' },
      { type: 'text-delta', index, text: answer.content },
      { type: 'block-end', index, block: { type: 'text', text: answer.content } },
    )
    index += 1
  }
  for (const [position, call] of answer.toolCalls.entries()) {
    const id = CallId(`${responseId}-${position}`)
    chunks.push(
      { type: 'block-start', index, blockType: 'tool-call' },
      { type: 'tool-call-delta', index, id, name: call.name, argumentsDelta: call.arguments },
      {
        type: 'block-end',
        index,
        block: { type: 'tool-call', id, name: call.name, arguments: call.arguments },
      },
    )
    index += 1
  }
  chunks.push({ type: 'usage', usage: mapUsage(usage) })
  chunks.push({
    type: 'finish',
    reason: answer.toolCalls.length > 0 ? { kind: 'tool-calls' } : { kind: 'stop' },
  })
  return chunks
}

