/** Probe one real query through the adapter and print the whole failure chain. */
import { query } from '@anthropic-ai/claude-agent-sdk'
import { scrubbedParentEnv } from '@deepseek-ai/dsh-subprocess'

const q = query({
  prompt: 'Say the single word ok.',
  options: {
    systemPrompt: 'You answer through the structured output only.',
    outputFormat: {
      type: 'json_schema',
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['content', 'toolCalls'],
        properties: {
          content: { type: 'string' },
          toolCalls: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              required: ['name', 'arguments'],
              properties: { name: { type: 'string' }, arguments: { type: 'string' } },
            },
          },
        },
      },
    },
    includePartialMessages: true,
    maxTurns: 1,
    permissionMode: 'dontAsk',
    tools: [],
    allowedTools: [],
    disallowedTools: ['AskUserQuestion'],
    mcpServers: {},
    strictMcpConfig: true,
    settingSources: [],
    persistSession: false,
    env: { ...scrubbedParentEnv() },
    stderr: (data: string) => { process.stderr.write(`[cli] ${data}`) },
  },
})

try {
  for await (const message of q) {
    if (message.type === 'stream_event') continue
    process.stdout.write(`${JSON.stringify(message).slice(0, 800)}\n`)
  }
} catch (error) {
  console.error('THROWN', error)
}

